from django.db import migrations, models

ACTIONS = ("view", "create", "assign", "resolve", "export")
SUPPORT_ACTIONS = ("assign", "resolve", "export")
# Mirrors seed_permissions: every role raises tickets; admin tiers and IT Support work them.
FULL_ACCESS_SLUGS = ("super-admin", "admin", "production-manager")
IT_SUPPORT_READ_CODES = (
    "dashboard.view",
    "lead.view",
    "call_log.view",
    "customer.view",
    "application.view",
    "sanction.view",
    "disbursal.view",
    "loan.view",
    "collection.view",
    "document.view",
)


def add_ticket_permissions(apps, schema_editor):
    """Grant help desk access and create the IT Support role without a re-seed."""
    Permission = apps.get_model("accounts", "Permission")
    Role = apps.get_model("accounts", "Role")
    RolePermission = apps.get_model("accounts", "RolePermission")
    UserRole = apps.get_model("accounts", "UserRole")

    perms = {}
    for action in ACTIONS:
        perms[action], _ = Permission.objects.get_or_create(
            module="ticket",
            action=action,
            defaults={"code": f"ticket.{action}"},
        )

    it_support, _ = Role.objects.get_or_create(
        slug="it-support",
        defaults={"name": "IT Support", "display_name": "IT"},
    )

    for role in Role.objects.all():
        actions = ("view", "create")
        if role.slug in FULL_ACCESS_SLUGS or role.pk == it_support.pk:
            actions = ACTIONS
        elif role.slug == "auditor":
            actions = ("view",)
        for action in actions:
            RolePermission.objects.get_or_create(role=role, permission=perms[action])

    for perm in Permission.objects.filter(code__in=IT_SUPPORT_READ_CODES):
        RolePermission.objects.get_or_create(role=it_support, permission=perm)

    from apps.accounts.services.permission_cache import invalidate_user_permissions

    for user_id in UserRole.objects.values_list("user_id", flat=True).distinct():
        invalidate_user_permissions(user_id)


def remove_ticket_permissions(apps, schema_editor):
    Permission = apps.get_model("accounts", "Permission")
    Role = apps.get_model("accounts", "Role")
    Permission.objects.filter(module="ticket").delete()
    Role.objects.filter(slug="it-support", user_roles__isnull=True).delete()


